using System;using System.Collections.Generic;using System.Net;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using System.IO;using System.Threading.Tasks;
namespace SoulboundLegends.NetworkTransport;
public sealed class UdpReliableTransportProvider:INetworkTransportProvider{
 sealed class Peer{public ulong Id;public IPEndPoint EndPoint;public ConnectionState State;public readonly Dictionary<TransportChannel,uint> SendSeqs=new();public readonly Dictionary<TransportChannel,uint> LastRecv=new();public readonly Dictionary<TransportChannel,uint> RecvBits=new();public DateTime LastReceive=DateTime.UtcNow,LastSend=DateTime.UtcNow;public double Rtt=100;public long SentBytes,RecvBytes,SentPackets,RecvPackets;public readonly Dictionary<(TransportChannel,uint),Pending> Reliable=new();public readonly Dictionary<TransportChannel,SortedDictionary<uint,byte[]>> Ordered=new();public readonly Dictionary<TransportChannel,uint> Expected=new();public byte[] ClientNonce;public byte[] ServerNonce;public string AuthToken;public string ReconnectToken;public RateLimiter Limiter=new(120,131072);}
 sealed class Pending{public byte[] Packet;public DateTime Sent;public int Attempts;public TransportChannel Channel;public uint Sequence;public Pending(byte[]p,TransportChannel c,uint s){Packet=p;Channel=c;Sequence=s;Sent=DateTime.UtcNow;}}
 readonly int maxPacket;readonly bool hmac;readonly byte[] secret;readonly Dictionary<ulong,Peer> peers=new();readonly Dictionary<string,(ulong id,DateTime until)> reconnect=new();readonly Socket socket=new(AddressFamily.InterNetwork,SocketType.Dgram,ProtocolType.Udp);readonly RandomNumberGenerator rng=RandomNumberGenerator.Create();readonly NetworkDiagnostics diagnostics=new();readonly string remoteTag;ulong nextId=1;bool server;ConnectionState state=ConnectionState.Disconnected;NetworkEndpoint endpoint;string clientToken;Peer clientPeer;DateTime lastTick=DateTime.UtcNow;public event Action<NetworkMessage> MessageReceived;public event Action<ulong> Connected;public event Action<ulong,string> Disconnected;public ConnectionState State=>state;public NetworkStats Stats{get{long sb=0,rb=0,sp=0,rp=0;double r=0;foreach(var p in peers.Values){sb+=p.SentBytes;rb+=p.RecvBytes;sp+=p.SentPackets;rp+=p.RecvPackets;r+=p.Rtt;}var n=Math.Max(1,peers.Count);return new NetworkStats(sb,rb,sp,rp,(float)(r/n),0,0,0);}}public UdpReliableTransportProvider(int maxPacketBytes=1200,bool enableHmac=true,string sharedSecret=""){maxPacket=Math.Max(256,maxPacketBytes);hmac=enableHmac;secret=Encoding.UTF8.GetBytes(sharedSecret??"");remoteTag="udp";}
 public void StartClient(NetworkEndpoint ep,string authToken,string reconnectToken=null){server=false;endpoint=ep;clientToken=authToken;socket.Bind(new IPEndPoint(IPAddress.Any,0));clientPeer=NewPeer(new IPEndPoint(Resolve(ep.Host),ep.Port));clientPeer.State=ConnectionState.Authenticating;clientPeer.AuthToken=authToken;clientPeer.ReconnectToken=reconnectToken;clientPeer.ClientNonce=RandomBytes(16);state=ConnectionState.Authenticating;using(var hw=new NetworkWriter()){hw.Write((byte)clientPeer.ClientNonce.Length);hw.Write(clientPeer.ClientNonce);hw.Write(reconnectToken??"");SendHandshake(clientPeer,NetworkMessageType.ClientHello,hw.ToArray());}}
 public void StartServer(int port){server=true;socket.Bind(new IPEndPoint(IPAddress.Any,port));state=ConnectionState.Connected;}
 Peer NewPeer(IPEndPoint ep){var p=new Peer{Id=server?nextId++:1,EndPoint=ep};foreach(TransportChannel c in Enum.GetValues(typeof(TransportChannel))){p.Ordered[c]=new SortedDictionary<uint,byte[]>();p.Expected[c]=1;p.SendSeqs[c]=0;p.LastRecv[c]=0;p.RecvBits[c]=0;}peers[p.Id]=p;return p;}
 static IPAddress Resolve(string h){if(IPAddress.TryParse(h,out var ip))return ip;return Dns.GetHostAddresses(h)[0];}static byte[] RandomBytes(int n){var b=new byte[n];RandomNumberGenerator.Fill(b);return b;}
 void SendHandshake(Peer p,NetworkMessageType t,byte[] payload){SendPacket(p,TransportChannel.ReliableOrdered,t,payload,true);}
 public void Send(ulong id,TransportChannel channel,NetworkMessageType type,ReadOnlySpan<byte> payload){if(!peers.TryGetValue(id,out var p)||p.State!=ConnectionState.Connected)return;if(payload.Length>maxPacket-PacketHeader.Size-(hmac?32:0))throw new ArgumentException("Payload exceeds configured MTU");SendPacket(p,channel,type,payload.ToArray(),false);}
 void SendPacket(Peer p,TransportChannel c,NetworkMessageType t,byte[] payload,bool handshake){var seq=++p.SendSeqs[c];var flags=(handshake?PacketFlags.Handshake:PacketFlags.None)|(hmac?PacketFlags.Authenticated:PacketFlags.None);var h=new PacketHeader(flags,c,t,p.Id,seq,p.LastRecv[c],p.RecvBits[c],(ushort)payload.Length,(ulong)DateTime.UtcNow.Ticks);var b=new byte[PacketHeader.Size+payload.Length+(hmac?32:0)];h.Write(b);Buffer.BlockCopy(payload,0,b,PacketHeader.Size,payload.Length);if(hmac){using var hm=new HMACSHA256(secret);var mac=hm.ComputeHash(b,0,PacketHeader.Size+payload.Length);Buffer.BlockCopy(mac,0,b,PacketHeader.Size+payload.Length,32);}socket.SendTo(b,p.EndPoint);p.SentBytes+=b.Length;p.SentPackets++;p.LastSend=DateTime.UtcNow;if(c==TransportChannel.ReliableOrdered||c==TransportChannel.ReliableUnordered)p.Reliable[(c,seq)]=new Pending(b,c,seq);}
 public void Tick(float dt){while(socket.Poll(0,SelectMode.SelectRead)){try{var buf=new byte[maxPacket+64];EndPoint ep=new IPEndPoint(IPAddress.Any,0);var n=socket.ReceiveFrom(buf,ref ep);HandlePacket(buf,n,(IPEndPoint)ep);}catch(Exception e){diagnostics.OnTransportError(e);break;}}var now=DateTime.UtcNow;foreach(var p in new List<Peer>(peers.Values)){if(p.State==ConnectionState.Connected||p.State==ConnectionState.Authenticating||p.State==ConnectionState.Reconnecting){if((now-p.LastReceive).TotalSeconds>8&&p.State!=ConnectionState.Reconnecting){p.State=ConnectionState.Reconnecting;Disconnected?.Invoke(p.Id,"timeout");}if(!server&&p.State==ConnectionState.Reconnecting&&(now-p.LastSend).TotalSeconds>=1){using(var hw=new NetworkWriter()){var cn=p.ClientNonce??RandomBytes(16);hw.Write((byte)cn.Length);hw.Write(cn);hw.Write(p.ReconnectToken??"");SendHandshake(p,NetworkMessageType.ClientHello,hw.ToArray());}}foreach(var x in new List<KeyValuePair<(TransportChannel,uint),Pending>>(p.Reliable))if((now-x.Value.Sent).TotalMilliseconds>150){if(x.Value.Attempts++>8){p.Reliable.Remove(x.Key);Disconnected?.Invoke(p.Id,"reliable_retry_exhausted");}else{socket.SendTo(x.Value.Packet,p.EndPoint);x.Value.Sent=now;}}if((now-p.LastSend).TotalSeconds>=1)SendPacket(p,TransportChannel.Unreliable,NetworkMessageType.Heartbeat,Array.Empty<byte>(),false);}}lastTick=now;}
 void HandlePacket(byte[] b,int n,IPEndPoint ep){if(n<PacketHeader.Size||n>maxPacket+64){diagnostics.OnSuspiciousTraffic("packet_size",ep.ToString());return;}if(!PacketHeader.TryRead(new ReadOnlySpan<byte>(b,0,n),out var h)||n<PacketHeader.Size+h.PayloadLength+(((h.Flags&PacketFlags.Authenticated)!=0)?32:0)){diagnostics.OnSuspiciousTraffic("malformed_header",ep.ToString());return;}Peer p=null;foreach(var q in peers.Values)if(q.EndPoint.Equals(ep)){p=q;break;}if(server&&p==null){p=NewPeer(ep);p.State=ConnectionState.Authenticating;}if(p==null)return;if((h.Flags&PacketFlags.Authenticated)!=0&&!VerifyHmac(b,n,h.PayloadLength)){diagnostics.OnSuspiciousTraffic("bad_hmac",ep.ToString());return;}p.RecvBytes+=n;p.RecvPackets++;p.LastReceive=DateTime.UtcNow;ProcessAck(p,h.Channel,h.Ack,h.AckBits);if(h.Sequence!=0&&!AcceptSequence(p,h.Channel,h.Sequence))return;var payload=new byte[h.PayloadLength];Buffer.BlockCopy(b,PacketHeader.Size,payload,0,h.PayloadLength);if(h.Type==NetworkMessageType.ClientHello&&server){try{var hr=new NetworkReader(payload);var nlen=hr.ReadByte();if(nlen!=16)throw new InvalidDataException("bad nonce");p.ClientNonce=new byte[nlen];for(int i=0;i<nlen;i++)p.ClientNonce[i]=hr.ReadByte();p.ReconnectToken=hr.ReadString(512);}catch{Disconnected?.Invoke(p.Id,"bad_client_hello");peers.Remove(p.Id);return;}if(!string.IsNullOrEmpty(p.ReconnectToken)&&reconnect.TryGetValue(p.ReconnectToken,out var restore)&&restore.until>DateTime.UtcNow){peers.Remove(p.Id);p.Id=restore.id;peers[p.Id]=p;}p.ServerNonce=RandomBytes(16);SendHandshake(p,NetworkMessageType.ServerChallenge,p.ServerNonce);return;}if(h.Type==NetworkMessageType.ServerChallenge&&!server){p.ServerNonce=payload;using var hm=new HMACSHA256(secret);using var m=new MemoryStream();m.Write(p.ClientNonce);m.Write(p.ServerNonce);m.Write(BitConverter.GetBytes(p.Id));m.Write(Encoding.UTF8.GetBytes(clientToken??""));using var aw=new NetworkWriter();aw.Write(clientToken??"");var proof=hm.ComputeHash(m.ToArray());aw.Write((ushort)proof.Length);aw.Write(proof);SendHandshake(p,NetworkMessageType.ClientAuthenticate,aw.ToArray());return;}if(h.Type==NetworkMessageType.ClientAuthenticate&&server){using var cr=new NetworkReader(payload);string suppliedToken;byte[] suppliedProof;try{suppliedToken=cr.ReadString(4096);int plen=cr.ReadUShort();suppliedProof=new byte[plen];for(int i=0;i<plen;i++)suppliedProof[i]=cr.ReadByte();}catch{Disconnected?.Invoke(p.Id,"authentication_malformed");peers.Remove(p.Id);return;}p.AuthToken=suppliedToken;using var hm=new HMACSHA256(secret);using var m=new MemoryStream();m.Write(p.ClientNonce);m.Write(p.ServerNonce);m.Write(BitConverter.GetBytes(p.Id));m.Write(Encoding.UTF8.GetBytes(p.AuthToken??""));if(secret.Length==0||suppliedProof.Length!=32||!CryptographicOperations.FixedTimeEquals(hm.ComputeHash(m.ToArray()),suppliedProof)){Disconnected?.Invoke(p.Id,"authentication_failed");peers.Remove(p.Id);return;}p.State=ConnectionState.Connected;var token=Convert.ToBase64String(RandomBytes(24));p.ReconnectToken=token;reconnect[token]=(p.Id,DateTime.UtcNow.AddSeconds(30));using var w=new NetworkWriter();w.Write(token);w.Write(p.Id);SendHandshake(p,NetworkMessageType.ServerAccept,w.ToArray());Connected?.Invoke(p.Id);return;}if(h.Type==NetworkMessageType.ServerAccept&&!server){p.State=ConnectionState.Connected;state=ConnectionState.Connected;Connected?.Invoke(p.Id);return;}if(h.Type==NetworkMessageType.Heartbeat)return;if(h.Type==NetworkMessageType.Disconnect){Disconnected?.Invoke(p.Id,"remote");peers.Remove(p.Id);return;}Deliver(p,h.Channel,h.Type,payload,h.Sequence);}
 bool VerifyHmac(byte[]b,int n,int len){if(secret.Length==0)return false;using var hm=new HMACSHA256(secret);var mac=hm.ComputeHash(b,0,PacketHeader.Size+len);for(int i=0;i<32;i++)if(mac[i]!=b[PacketHeader.Size+len+i])return false;return true;}
 bool AcceptSequence(Peer p,TransportChannel c,uint seq){uint last=p.LastRecv[c];uint bits=p.RecvBits[c];if(seq>last){uint shift=seq-last;bits=shift>=32?0:(bits<<((int)shift));if(shift<32&&last!=0)bits|=1u<<(int)(shift-1);p.LastRecv[c]=seq;p.RecvBits[c]=bits;return true;}uint d=last-seq;if(d==0)return false;if(d<=32){uint bit=1u<<(int)(d-1);if((bits&bit)!=0)return false;p.RecvBits[c]=bits|bit;}return false;}
 void ProcessAck(Peer p,TransportChannel channel,uint ack,uint bits){foreach(var kv in new List<KeyValuePair<(TransportChannel,uint),Pending>>(p.Reliable))if(kv.Key.Item1==channel){uint s=kv.Key.Item2;if(s==ack||(s<ack&&ack-s<=32&&(bits&(1u<<(int)(ack-s-1)))!=0)){var pending=kv.Value;p.Rtt=(p.Rtt*.8)+((DateTime.UtcNow-pending.Sent).TotalMilliseconds*.2);p.Reliable.Remove(kv.Key);}}}
 void Deliver(Peer p,TransportChannel c,NetworkMessageType t,byte[] payload,uint seq){if(c==TransportChannel.UnreliableSequenced&&seq<p.LastRecv[c])return;if(c==TransportChannel.ReliableOrdered){var expected=p.Expected[c];if(seq<expected)return;if(seq>expected){p.Ordered[c][seq]=payload;return;}MessageReceived?.Invoke(new NetworkMessage(p.Id,c,t,payload,seq));p.Expected[c]++;while(p.Ordered[c].Remove(p.Expected[c],out var next)){MessageReceived?.Invoke(new NetworkMessage(p.Id,c,t,next,p.Expected[c]));p.Expected[c]++;}}else MessageReceived?.Invoke(new NetworkMessage(p.Id,c,t,payload,seq));}
 public void Disconnect(ulong id,string reason){if(!peers.TryGetValue(id,out var p))return;using var w=new NetworkWriter();w.Write(reason??"");SendPacket(p,TransportChannel.ReliableOrdered,NetworkMessageType.Disconnect,w.ToArray(),false);peers.Remove(id);Disconnected?.Invoke(id,reason);}
 public void Dispose(){socket.Close();foreach(var p in peers.Values)Disconnected?.Invoke(p.Id,"disposed");peers.Clear();state=ConnectionState.Disconnected;}
}
